// Parsea el payload de Mailgun (inbound webhook).
// Mailgun manda multipart/form-data con campos como 'sender', 'From', 'subject',
// 'body-plain', 'stripped-text', 'attachment-count', 'attachment-1', 'attachment-2', ...
// También sirve para Postmark (que manda JSON con 'FromFull', 'TextBody', 'Attachments')
// y providers similares.

const body = $input.first().json.body || {};

// Sender: 'sender' (Mailgun clean) > 'from' > 'From' > 'FromFull.Email' (Postmark)
const sender = body.sender || body.from || body.From || body.FromFull?.Email || 'desconocido@email';

// Subject
const subject = body.subject || body.Subject || '(sin asunto)';

// Body de texto: preferir 'stripped-text' (sin firma/quotes), fallback a 'body-plain'
const text =
  body['stripped-text']
  || body['body-plain']
  || body.TextBody           // Postmark
  || body.text
  || body.StrippedTextReply  // Postmark
  || '';

// Attachments: Mailgun manda 'attachment-1', 'attachment-2', ... como campos separados
// O 'attachments' como array (Mailgun API newer). Postmark manda 'Attachments'.
const media = [];
if (Array.isArray(body.attachments)) {
  for (const a of body.attachments) {
    media.push({
      type: (a['content-type'] || a.ContentType || '').startsWith('image/') ? 'image' : 'file',
      url: a.url || a.ContentURL || null,
      mime_type: a['content-type'] || a.ContentType,
      name: a.name || a.Name,
      size: a.size || a.ContentLength,
    });
  }
} else if (Array.isArray(body.Attachments)) {
  for (const a of body.Attachments) {
    media.push({
      type: (a.ContentType || '').startsWith('image/') ? 'image' : 'file',
      url: a.ContentURL || null,
      mime_type: a.ContentType,
      name: a.Name,
      size: a.ContentLength,
    });
  }
} else if (body['attachment-count']) {
  const count = Number(body['attachment-count']) || 0;
  for (let i = 1; i <= count; i++) {
    const a = body[`attachment-${i}`];
    if (a) {
      media.push({
        type: (a['content-type'] || '').startsWith('image/') ? 'image' : 'file',
        url: a.url || null,
        mime_type: a['content-type'],
        name: a.name,
        size: a.size,
      });
    }
  }
}

return { sender, subject, text, media };

// Elige la mejor foto adjunta del correo (formato Postmark: base64 en Content).
// Heuristicas anti-logo de firmas/banners en correos reenviados:
//   1. preferir adjuntos reales (sin ContentID) sobre incrustados en el cuerpo
//   2. descartar imagenes < 50KB (logos, pixeles de tracking)
//   3. entre las que queden, la mas grande
const body = $('Webhook Email').first().json.body || {};
const pubId = $input.first().json.id;
const atts = Array.isArray(body.Attachments) ? body.Attachments : [];
const IMG = new Set(['image/jpeg', 'image/png', 'image/webp']);
const MIN_BYTES = 50 * 1024;

const mimeOf = (a) => String(a.ContentType || '').toLowerCase().split(';')[0].trim();
const sizeOf = (a) => Number(a.ContentLength) || Math.floor(String(a.Content || '').length * 3 / 4);

const cands = atts
  .filter((a) => IMG.has(mimeOf(a)) && a.Content)
  .map((a) => ({ ...a, _size: sizeOf(a) }))
  .filter((a) => a._size >= MIN_BYTES);

const reales = cands.filter((a) => !a.ContentID);
const pool = reales.length ? reales : cands;
pool.sort((a, b) => b._size - a._size);
const best = pool[0] || null;

return {
  id: pubId,
  hasImage: !!best,
  contentBase64: best ? best.Content : null,
  contentType: best ? mimeOf(best) : null,
  originalName: best ? (best.Name || 'foto') : null,
};

