=UPDATE publications
SET source_media = '{{ JSON.stringify([{ type: 'image', url: $json.url, origin: 'email', name: $('Pick Best Image').item.json.originalName }]).replace(/'/g, "''") }}'::jsonb
WHERE id = '{{ $('Pick Best Image').item.json.id }}'::uuid RETURNING id;
